"""`.SVS`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.SVS'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Force visibility', 'NodeSocketInt', subtype='FACTOR', min_value=0, max_value=2)
    t.socket('INPUT', 'Dark', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Light', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Normal', 'NodeSocketColor', default_value=(0.5, 0.5, 1.0, 1.0))
    t.socket('INPUT', 'Normal alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Normal detail', 'NodeSocketColor')
    t.socket('INPUT', 'Normal detail alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Permalight mask', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha mask', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Light alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Alpha mask bottom', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Alpha mask alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Alpha mask bottom alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Hidden', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (806.7309, -5.228149),
    })
    t.node('NodeGroupInput', 'Group Input', hide_outputs=('Dark', 'Light', 14), props={
        'location': (-932.7909, -89.14188),
        'width': 219.59851,
    })
    t.node('ShaderNodeMixShader', 'Mix Shader', props={
        'location': (362.77213, 116.04548),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', hide_inputs=('Color', 'Weight'), props={
        'location': (189.13348, -61.66092),
    })
    t.node('ShaderNodeMix', 'mix', inputs={'Factor_Float': 0.5}, hide_inputs=('Factor_Vector', 'A_Float', 'B_Float', 'A_Vector', 'B_Vector'), outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, hide_outputs=('Result_Float', 'Result_Vector'), props={
        'location': (10.933739, 139.93631),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeGroup', 'shade', inputs={'Use Normals?': 0.0}, props={
        'node_tree': lib.group('.Toon shading'),
        'location': (-586.2891, 32.613213),
        'width': 247.78687,
    })
    t.node('ShaderNodeGroup', 'Group', props={
        'node_tree': lib.group('.SVS alphamask parser'),
        'location': (-586.4617, -236.55406),
        'width': 244.67352,
    })
    t.node('NodeGroupInput', 'Group Input.001', hide_outputs=('Force visibility', 'Normal', 'Normal alpha', 'Normal detail', 'Normal detail alpha', 'Permalight mask', 'Alpha mask', 'Light alpha', 'Alpha mask bottom', 'Alpha mask alpha', 'Alpha mask bottom alpha', 'Hidden', 14), props={
        'location': (-173.46387, -35.007374),
        'width': 128.83057,
    })
    t.node('ShaderNodeBsdfTransparent', 'hidden.transparent', props={
        'location': (406.7309, -155.22815),
        'label': 'hidden.transparent',
    })
    t.node('ShaderNodeMixShader', 'hidden.mix', props={
        'location': (586.7309, -5.228149),
        'label': 'hidden.mix',
    })

    t.link('Transparent BSDF', 'BSDF', 'Mix Shader', 'Shader')
    t.link('mix', 'Result_Color', 'Mix Shader', 'Shader_001')
    t.link('shade', 'Toon shading', 'mix', 'Factor_Float')
    t.link('Group', 'Value', 'Mix Shader', 'Fac')
    t.link('Group Input', 'Normal detail', 'shade', 'Normal detail color')
    t.link('Group Input', 'Normal alpha', 'shade', 'Normal alpha')
    t.link('Group Input', 'Alpha mask bottom', 'Group', 2)
    t.link('Group Input', 'Alpha mask', 'Group', 0)
    t.link('Group Input', 'Alpha mask alpha', 'Group', 4)
    t.link('Group Input', 'Normal', 'shade', 'Normal color')
    t.link('Group Input', 'Force visibility', 'Group', 3)
    t.link('Group Input', 'Normal detail alpha', 'shade', 'Normal detail alpha')
    t.link('Group Input', 'Permalight mask', 'shade', 'Permalight mask')
    t.link('Group Input', 'Alpha mask bottom alpha', 'Group', 5)
    t.link('Group Input', 'Light alpha', 'Group', 1)
    t.link('Group Input.001', 'Dark', 'mix', 'A_Color')
    t.link('Group Input.001', 'Light', 'mix', 'B_Color')
    t.link('Mix Shader', 'Shader', 'hidden.mix', 'Shader')
    t.link('hidden.transparent', 'BSDF', 'hidden.mix', 'Shader_001')
    t.link('Group Input', 'Hidden', 'hidden.mix', 'Fac')
    t.link('hidden.mix', 'Shader', 'Group Output', 'Shader')
    return t
